def seed_estimate_services(apps, schema_editor):
    """Create one disabled pricing row per public service.

    Prices start empty on purpose. The shop owner enters every number; the
    site never seeds an invented price or turns a service on by itself.
    """
    EstimateService = apps.get_model("mapleleaf_app", "EstimateService")
    from mapleleaf_app.content import SERVICES

    for index, service in enumerate(SERVICES):
        defaults = {"display_order": index}
        if service["slug"] in {"collision", "paint"}:
            defaults["uses_severity"] = True
        EstimateService.objects.get_or_create(slug=service["slug"], defaults=defaults)


def remove_estimate_services(apps, schema_editor):
    EstimateService = apps.get_model("mapleleaf_app", "EstimateService")
    EstimateService.objects.all().delete()


